1: import { execSync } from 'node:child_process';
2: import { success, error } from '../output.js';
3: import { requireConfig, withDefaults } from '../config.js';
4: import { findActiveSession, appendEvidence, loadEvidence } from '../session.js';
5: import { resolve } from 'node:path';
6: 
7: export function registerPrerequisite(program) {
8:   program
9:     .command('prerequisite')
10:     .description('Record an environment prerequisite')
11:     .argument('<description>', 'Prerequisite description')
12:     .option('--check <command>', 'Command to verify the prerequisite')
13:     .action(async (description, opts) => {
14:       const config = withDefaults(requireConfig('prerequisite'));
15:       const evidenceDir = resolve(config._dir, config.session.evidence_dir);
16:       const active = findActiveSession(evidenceDir);
17:       if (!active) {
18:         error('prerequisite', 'No active session. Run `proofrun session start --change <name> --device <identifier>` first.');
19:       }
20: 
21:       const entryData = {
22:         type: 'prerequisite',
23:         description,
24:       };
25: 
26:       if (opts.check) {
27:         entryData.check_command = opts.check;
28:         try {
29:           const output = execSync(opts.check, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] });
30:           entryData.check_output = output.trim();
31:           entryData.check_passed = true;
32:         } catch (err) {
33:           entryData.check_output = (err.stdout || err.stderr || '').trim();
34:           entryData.check_passed = false;
35:         }
36:       }
37: 
38:       const entry = appendEvidence(active.sessionDir, entryData);
39: 
40:       const evidence = loadEvidence(active.sessionDir);
41:       const checkInfo = opts.check
42:         ? ` [check: ${entry.check_passed ? 'passed' : 'FAILED'}]`
43:         : '';
44: 
45:       success('prerequisite', {
46:         entry_id: entry.id,
47:         type: 'prerequisite',
48:         description: entry.description,
49:         check_command: entry.check_command || null,
50:         check_output: entry.check_output || null,
51:         check_passed: entry.check_passed != null ? entry.check_passed : null,
52:         timestamp: entry.timestamp,
53:         total_entries: evidence.entries.length,
54:       }, (data) =>
55:         `Prerequisite recorded [#${data.entry_id}]${checkInfo}: ${data.description}`
56:       );
57:     });
58: }
